from pathlib import Path
import json,shutil,sys
b=Path(__file__).resolve().parent.parent;src=Path(sys.argv[1]);dest=b/'Captures';dest.mkdir(exist_ok=True)
files=sorted(src.glob('Mechanics_*.png'));assert files
for p in files:shutil.copy2(p,dest/p.name)
def selected(part):return sorted([p.name for p in files if part in p.name],key=lambda x:('Before' not in x,x))
groups=[{'title':'New obstacle family','files':selected('ObstaclesR9_')+selected('Seal_')}, {'title':'Bomb — charge, blast, fragments','files':selected('BombR9_')}, {'title':'Directional power-up','files':selected('LineR9_')},{'title':'Spark — flight and arrival','files':selected('SparkR9_')},{'title':'Inventory booster gestures','files':selected('InventoryR9_')},{'title':'Five rounds and clearer instructions','files':selected('Round_')}]
assert all(g['files'] for g in groups)
(b/'QA/CaptureManifest.json').write_text(json.dumps(groups,indent=2))
